       const inputId = option.id;
       const checkbox = createEl("input", {
         id: inputId,
         name: questionId,
         type: "checkbox",
         value: option.label
       });

       checkbox.addEventListener("change", () => {
         state[questionId] = Array.from(document.querySelectorAll(`input[name="${questionId}"]:checked`)).map((input) => input.value);
       });

       return createEl(
         "label",
         { className: "choice", htmlFor: inputId },
         [
           checkbox,
           createEl("div", {}, [
             createEl("span", { textContent: option.label }),
             createEl("small", { textContent: option.detail })
           ])
         ]
       );
     }

     function QuestionField(question, index) {
       const legendId = `${question.id}-legend`;
       const helpId = question.help ? `${question.id}-help` : null;

       const fieldset = createEl("fieldset", {
         "aria-describedby": helpId || undefined
       });

       fieldset.append(
         createEl("legend", { id: legendId }, [
           question.title,
           question.help ? createEl("span", { className: "required-mark", "aria-hidden": "true", textContent: " *" }) : ""
         ])
       );

       if (question.help) {
         fieldset.append(createEl("p", { id: helpId, className: "help-text", textContent: question.help }));
       }

       const options = createEl("div", { className: "option-list" }, question.options.map((option) => ChoiceOption(question.id, option)));
       fieldset.append(options);

       return createEl("div", { className: "form-field" }, [fieldset]);
     }

     function QuizApp() {
       const main = createEl("main", { id: "main", className: "page-shell" });
       const header = createEl("header", {}, [
         createEl("h1", { textContent: "Computer Languages Quiz" }),
         createEl("p", {
           className: "lede",
           textContent: "Pick every answer you think fits each question. This quiz uses checkboxes so multiple selections are possible for every prompt."
         })
       ]);

       const form = createEl("form", { novalidate: "novalidate" });

       quizData.forEach((question, index) => {
         form.append(QuestionField(question, index));
       });

       const status = createEl("p", {
         className: "status",
         id: "quiz-status",
         role: "status",
         "aria-live": "polite"
       });

       const submit = createEl("button", { type: "submit", textContent: "Submit answers" });
       const actions = createEl("div", { className: "actions" }, [submit, status]);

       form.append(actions);

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const summary = quizData.map((question) => {
           const checked = Array.from(form.querySelectorAll(`input[name="${question.id}"]:checked`)).map((input) => input.value);
           return `${question.title} ${checked.length ? checked.join(", ") : "no answers selected"}`;
         });

         status.dataset.state = "success";
         status.textContent = `Saved selections. ${summary.join(" • ")}`;
       });

       main.append(header, createEl("section", { className: "quiz-card", "aria-label": "Quiz form" }, [form]));
       return main;
     }

     document.getElementById("app").append(QuizApp());
   </script>
 </body>
 </html>

